from pathlib import Path
import sys
root=Path(sys.argv[1])
p=root/'scripts/infra03/trust.py'; s=p.read_text()
needle='.add_extension(x509.BasicConstraints(ca=True, path_length=0), critical=True)\n'
repl=needle+'            .add_extension(x509.SubjectKeyIdentifier.from_public_key(self._key.public_key()), critical=False)\n            .add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(self._key.public_key()), critical=False)\n'
if 'SubjectKeyIdentifier.from_public_key(self._key.public_key())' not in s: s=s.replace(needle,repl)
needle='.add_extension(x509.BasicConstraints(ca=False, path_length=None), critical=True)\n'
repl=needle+'            .add_extension(x509.SubjectKeyIdentifier.from_public_key(key.public_key()), critical=False)\n            .add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(self._key.public_key()), critical=False)\n'
if 'SubjectKeyIdentifier.from_public_key(key.public_key())' not in s: s=s.replace(needle,repl)
